def get_env_value(key, default=None, env_file='.env'):
    """
    Read a key from a .env file, returning the value or the provided default if the key is not found.

    Args:
        key (str): The key to look up in the .env file.
        default (str, optional): The default value to return if the key is not found.
        env_file (str, optional): Path to the `.env` file (default: '.env').

    Returns:
        str: The value of the key, or the default if the key is not present.
    """
    try:
        with open(env_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    if k == key:
                        return v
    except FileNotFoundError:
        return default
    return default

