def print_aligned_table(records):
    if not records:
        return

    # Get the headers
    headers = records[0].keys()

    # Get the rows as lists for easier processing
    rows = [list(record.values()) for record in records]

    # Determine maximum width for each column
    max_widths = []
    for col in zip(*rows):
        max_widths.append(max(len(str(cell)) for cell in col))

    # Print header row with aligned columns
    for header, width in zip(headers, max_widths):
        print(f"{header:<{width}}", end=' ')
    print()

    # Print data rows
    for row in rows:
        for cell, width in zip(row, max_widths):
            print(f"{cell:<{width}}", end=' ')
        print()

