import json
from typing import Any, Dict, Union

def validate_request(json_input: str, model_def: Dict[str, str]) -> Dict[str, Any]:
    """
    Validate JSON input against a model defined as a dictionary of field types.

    Args:
        json_input: JSON string containing the request body.
        model_def: Dictionary where keys are field names and values are expected types.
    """
    data = json.loads(json_input)
    for field, expected_type in model_def.items():
        if field not in data:
            raise ValueError(f"Missing field: {field}")
        value = data[field]
        if expected_type == "str" and not isinstance(value, str):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of str")
        elif expected_type == "int" and not isinstance(value, int):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of int")
        elif expected_type == "bool" and not isinstance(value, bool):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of bool")
        elif expected_type == "float" and not isinstance(value, float):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of float")
        elif expected_type == "list" and not isinstance(value, list):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of list")
        elif expected_type == "dict" and not isinstance(value, dict):
            raise ValueError(f"Field {field} has incorrect type: {type(value)} instead of dict")
        else:
            raise ValueError(f"Unsupported type: {expected_type}")
    return data

