import time
from functools import wraps

def cache_with_ttl(ttl):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            # Generate a consistent key based on arguments
            sorted_kwargs = sorted(kwargs.items())
            key = (args, tuple(sorted_kwargs))

            if key in cache:
                current_time = time.time()
                if current_time - cache[key]['timestamp'] > ttl:
                    del cache[key]
                else:
                    return cache[key]['result']

            # Call the original function
            result = func(*args, **kwargs)
            cache[key] = {'result': result, 'timestamp': time.time()}
            return result
        return wrapper
    return decorator

