import phonenumbers

def format_phone_number(phone_str: str) -> str:
    """
    Validate and format a phone number into international (E.164) format.

    Args:
        phone_str (str): A string representing a phone number (e.g., '+14085550123').

    Returns:
        str: Formatted phone number in E.164 format if valid, or an error message.

    Raises:
        phonenumbers.NumberParseException: If the input is not a valid phone number.
    """
    try:
        number = phonenumbers.parse(phone_str, None)
        if phonenumbers.is_valid_number(number):
            return phonenumbers.format_number(number, phonenumbers.PhoneNumberFormat.E164)
        else:
            return "Invalid phone number"
    except phonenumbers.NumberParseException as e:
        return f"Phone number parsing error: {e}"
    except Exception as e:
        return f"Unexpected error: {e}"

def levenshtein(s1: str, s2: str) -> int:
    """
    Computes the Levenshtein distance between two strings using dynamic programming.
    """
    if len(s1) < len(s2):
        return levenshtein(s2, s1)

    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and column
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Compute the rest of the table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,   # Deletion
                dp[i][j - 1] + 1,   # Insertion
                dp[i - 1][j - 1] + cost  # Substitution
            )

    return dp[n][m]


def closest_match(query: str, names: list) -> str:
    """
    Returns the name in 'names' that is closest to the 'query' string.
    - Exact match is prioritized.
    - Ties are broken by returning the first name with the smallest distance.
    """
    if not names:
        return None

    # Check for exact match
    for name in names:
        if name == query:
            return name

    # Compute Levenshtein distances and find the closest match
    min_distance = float('inf')
    closest_name = None

    for name in names:
        distance = levenshtein(query, name)
        if distance < min_distance:
            min_distance = distance
            closest_name = name

    return closest_name

import time

# Module-level cache for decorated functions
_cache = {}

def cache_with_ttl(ttl):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Create a hashable key based on positional and sorted keyword arguments
            key = (args, tuple(sorted(kwargs.items())))

            # Check if result is already in the cache and not expired
            if key in _cache:
                current_time = time.time()
                if current_time < _cache[key][1]:
                    return _cache[key][0]

            # Compute the result and store it with an expiration time
            result = func(*args, **kwargs)
            _cache[key] = (result, time.time() + ttl)
            return result

        return wrapper
    return decorator

def closest_match(query: str, names: list) -> str:
    """
    Find the name in the list that is closest to the given query string,
    using Levenshtein distance.

    Args:
        query (str): The string to compare against.
        names (list): A list of strings to compare.

    Returns:
        str: The name in the list that is closest to the query.
    """

    def levenshtein(s1: str, s2: str) -> int:
        """
        Compute the Levenshtein distance between s1 and s2.
        """
        if len(s1) < len(s2):
            return levenshtein(s2, s1)
        # s1 is longer, we'll use it for efficiency
        m, n = len(s2), len(s1)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s2[i - 1] == s1[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(
                        dp[i - 1][j],    # deletion
                        dp[i][j - 1],    # insertion
                        dp[i - 1][j - 1]  # substitution
                    )
        return dp[m][n]

    min_distance = float('inf')
    closest = None

    for name in names:
        distance = levenshtein(query, name)
        if distance < min_distance:
            min_distance = distance
            closest = name

    return closest
